        "rolo-docs-beacon-v1-1-12-research-beacon-practice-boundary-learning-analysis-md",
        "rolo-docs-beacon-v1-1-12-research-beacon-requirement-anchor-divergence-closure-analysis-md",
        "rolo-docs-beacon-v1-3-6-qa-test-cases-beacon-v1-3-6-visual-management-console-and-material-viewer-md",
        "rolo-docs-beacon-v1-3-4-qa-test-cases-beacon-v1-3-4-global-runtime-projection-and-pocketbase-control-plane-md"
